From a3d95dcc711d511e20c3344bc8be959f2d768a9a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:40:23 +0100
Subject: [PATCH] wireguard: accept allowed IPs without a prefix length

A peer's Allowed IPs only accepted addresses with a CIDR prefix, so a
plain address like 192.168.0.1 kept the field red and OK disabled. Treat
it as a single host, like wg-quick and NetworkManager already do.

BUG: 452491
---
 libs/editor/settings/wireguardpeerwidget.cpp | 14 +++++++++-----
 1 file changed, 9 insertions(+), 5 deletions(-)

diff --git a/libs/editor/settings/wireguardpeerwidget.cpp b/libs/editor/settings/wireguardpeerwidget.cpp
index d6edef274..6421bce4d 100644
--- a/libs/editor/settings/wireguardpeerwidget.cpp
+++ b/libs/editor/settings/wireguardpeerwidget.cpp
@@ -35,6 +35,7 @@

 static WireGuardKeyValidator keyValidator;
 static SimpleIpListValidator allowedIPsValidator(SimpleIpListValidator::WithCidr, SimpleIpListValidator::Both);
+static SimpleIpListValidator allowedHostsValidator(SimpleIpListValidator::Base, SimpleIpListValidator::Both);

 class WireGuardPeerWidget::Private
 {
@@ -141,19 +142,22 @@ void WireGuardPeerWidget::checkPresharedKeyValid()

 void WireGuardPeerWidget::checkAllowedIpsValid()
 {
-    int pos = 0;
     QLineEdit *widget = d->ui.allowedIPsLineEdit;
     QString ipString = widget->displayText();
     QStringList rawIPList = ipString.split(QLatin1Char(','));
     QStringList ipList;
+    bool valid = true;

-    bool valid = QValidator::Acceptable == allowedIPsValidator.validate(ipString, pos);
-    setBackground(widget, valid);
-
+    // An address without a prefix length is a single host, like in wg-quick files
     ipList.reserve(rawIPList.size());
     for (const QString &ip : rawIPList) {
-        ipList.append(ip.trimmed());
+        QString address = ip.trimmed();
+        int pos = 0;
+        valid = valid
+            && (allowedIPsValidator.validate(address, pos) == QValidator::Acceptable || allowedHostsValidator.validate(address, pos) == QValidator::Acceptable);
+        ipList.append(address);
     }
+    setBackground(widget, valid);

     d->peerData[PNM_WG_PEER_KEY_ALLOWED_IPS] = ipList;
     if (valid != d->allowedIPsValid) {
-- 
